@namespace sv_4efb35aebd914dbe9a474e67beb089c0.Components.Pages.Apply

<h3>References</h3>
<p class="hint">Please provide 2–3 professional references.</p>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <div class="entry-card">
        <h4>Reference @(index + 1)</h4>
        <ReferenceForm Entry="@References[index]"
                       EntryChanged="e => UpdateReference(index, e)"
                       CanRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(index)" />
    </div>
}

@if (References.Count < 3)
{
    <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
}

<div class="step-buttons">
    <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
    <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> ReferencesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        await ReferencesChanged.InvokeAsync(References);
        await OnNext.InvokeAsync();
    }
}

