@namespace sv_4efb35aebd914dbe9a474e67beb089c0.Components.Pages.Apply

<h3>Review & Submit</h3>

@if (IsSubmitted)
{
    <div class="confirmation">
        <h2>&#10003; Application Submitted!</h2>
        <p>Your application ID is: <strong>@ApplicationId</strong></p>
        <p>Thank you for applying. We will be in touch soon.</p>
    </div>
}
else
{
    <div class="review-section">
        <div class="review-header">
            <h4>Personal Information</h4>
            <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Full Name</dt><dd>@FullName</dd>
            <dt>Email</dt><dd>@Email</dd>
            <dt>Phone</dt><dd>@Phone</dd>
            <dt>Address</dt><dd>@Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>Work History</h4>
            <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-entry">
                <strong>@entry.Title</strong> at @entry.Company<br />
                <span class="date-range">
                    @entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                </span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>References</h4>
            <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="review-entry">
                <strong>@r.Name</strong> (@r.Relationship)<br />
                @r.Email | @r.Phone
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-header">
            <h4>Cover Letter</h4>
            <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
}

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

arguments.file_text:
@page "/apply"
@using sv_4efb35aebd914dbe9a474e67beb089c0.Components.Pages.Apply
@using sv_4efb35aebd914dbe9a474e67beb089c0.Models
@using sv_4efb35aebd914dbe9a474e67beb089c0.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="step-content">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@fullName" FullNameChanged="v => fullName = v"
                                  Email="@email" EmailChanged="v => email = v"
                                  Phone="@phone" PhoneChanged="v => phone = v"
                                  Address="@address" AddressChanged="v => address = v"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="NextStep" />
                break;
            case 1:
                <WorkHistoryStep Entries="@workEntries"
                                 EntriesChanged="v => workEntries = v"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="@references"
                                ReferencesChanged="v => references = v"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 CoverLetterChanged="v => coverLetter = v"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep FullName="@fullName" Email="@email"
                            Phone="@phone" Address="@address"
                            WorkEntries="@workEntries"
                            References="@references"
                            CoverLetter="@coverLetter"
                            IsSubmitting="@isSubmitting"
                            IsSubmitted="@isSubmitted"
                            ApplicationId="@applicationId"
                            ErrorMessage="@submitError"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    // Personal Info
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Work History
    private List<WorkEntry> workEntries = new()
    {
        new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty)
    };

    // References
    private List<Reference> references = new()
    {
        new Reference(string.Empty, string.Empty, string.Empty, string.Empty),
        new Reference(string.Empty, string.Empty, string.Empty, string.Empty)
    };

    // Cover Letter
    private string coverLetter = string.Empty;

    // Submission
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries),
                references,
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 0.85;
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
}

.step.active .step-circle {
    background: #1976d2;
    color: white;
}

.step.completed .step-circle {
    background: #4caf50;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 80px;
}

.step-connector {
    width: 40px;
    height: 2px;
    background: #e0e0e0;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1.25rem;
}

.step-connector.completed {
    background: #4caf50;
}

/* Form Elements */
.step-content {
    background: #fafafa;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
