@page "/apply"
@using sv_4efb35aebd914dbe9a474e67beb089c0.Components.Pages.Apply
@using sv_4efb35aebd914dbe9a474e67beb089c0.Models
@using sv_4efb35aebd914dbe9a474e67beb089c0.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="step-content">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@fullName" FullNameChanged="v => fullName = v"
                                  Email="@email" EmailChanged="v => email = v"
                                  Phone="@phone" PhoneChanged="v => phone = v"
                                  Address="@address" AddressChanged="v => address = v"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="NextStep" />
                break;
            case 1:
                <WorkHistoryStep Entries="@workEntries"
                                 EntriesChanged="v => workEntries = v"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="@references"
                                ReferencesChanged="v => references = v"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 CoverLetterChanged="v => coverLetter = v"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep FullName="@fullName" Email="@email"
                            Phone="@phone" Address="@address"
                            WorkEntries="@workEntries"
                            References="@references"
                            CoverLetter="@coverLetter"
                            IsSubmitting="@isSubmitting"
                            IsSubmitted="@isSubmitted"
                            ApplicationId="@applicationId"
                            ErrorMessage="@submitError"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    // Personal Info
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Work History
    private List<WorkEntry> workEntries = new()
    {
        new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty)
    };

    // References
    private List<Reference> references = new()
    {
        new Reference(string.Empty, string.Empty, string.Empty, string.Empty),
        new Reference(string.Empty, string.Empty, string.Empty, string.Empty)
    };

    // Cover Letter
    private string coverLetter = string.Empty;

    // Submission
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries),
                references,
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

