toolArgs.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 0.85;
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
}

.step.active .step-circle {
    background: #1976d2;
    color: white;
}

.step.completed .step-circle {
    background: #4caf50;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 80px;
}

.step-connector {
    width: 40px;
    height: 2px;
    background: #e0e0e0;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1.25rem;
}

.step-connector.completed {
    background: #4caf50;
}

/* Form Elements */
.step-content {
    background: #fafafa;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

.btn-primary {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-primary:disabled {
    background: #90caf9;
    cursor: not-allowed;
}

.btn-outline {
    background: transparent;
    color: #1976d2;
    border: 1px solid #1976d2;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-outline:hover {
    background: #e3f2fd;
}

.btn-secondary {
    background: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #eeeeee;
}

.btn-danger {
    background: transparent;
    color: #d32f2f;
    border: 1px solid #d32f2f;
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    font-size: 0.85rem;
    cursor: pointer;
}

.btn-danger:hover {
    background: #ffebee;
}

.btn-link {
    background: none;
    border: none;
    color: #1976d2;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Entry Cards */
.entry-card {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.entry-card h4 {
    margin: 0 0 1rem 0;
    color: #555;
}

/* Review */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #e0e0e0;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h4 {
    margin: 0 0 0.5rem 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #666;
}

.review-entry {
    margin: 0.5rem 0;
    padding: 0.5rem;
    background: white;
    border-radius: 4px;
}

.date-range {
    color: #666;
    font-size: 0.9rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: white;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #eee;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #d32f2f;
    font-weight: bold;
}

/* Messages */
.error-message {
    background: #ffebee;
    color: #c62828;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    border: 1px solid #ef9a9a;
}

.validation-spinner {
    font-size: 0.85rem;
    color: #1976d2;
    font-style: italic;
}

.hint {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation h2 {
    color: #4caf50;
    margin-bottom: 1rem;
}

.confirmation p {
    font-size: 1.1rem;
    color: #555;
}

